using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Quantum.Entanglement.PartialTransposeSaturation;

internal sealed class PartialTransposeSaturationSingularDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/Quantum/Entanglement/PartialTransposeSaturation/Singular.";
    private static readonly LibraryNoteRef Source =
        LibraryNoteRef.Create("D5/L/Eigenstructure/wangchen2025partialtranspose");

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Exact tensor ranks of extracted singular chains", H("Singular chains"),
        Blocks(
            Paragraph(Text("The construction treats a pair of complex linear maps on finite dimensional spaces. Kernel chains are split by commuting source and target projections. Their actual span bases identify the restricted arrows with rectangular singular pencil blocks. Common zero rows and columns are retained through zero index blocks. Classical matrix pencil decompositions provide the context; the chain splitting and tensor rank arguments here are proved directly.")),
            Describe.Lean(DescribeId.Create("righte"),
                DeclarationHandle.Create(Prefix + "rightE"), H("Truncated identity coefficient"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(Source),
                Blocks(Paragraph(Text("The r by r+1 complex matrix with an identity in the first r columns and a final zero column."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("rightf"),
                DeclarationHandle.Create(Prefix + "rightF"), H("Shift coefficient"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(Source),
                Blocks(Paragraph(Text("The r by r+1 complex matrix with an initial zero column followed by an identity."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("source"),
                DeclarationHandle.Create(Prefix + "source"), H("Extracted source span"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(Source),
                Blocks(Paragraph(Text("The complex span of the independent coefficient vectors in an extracted polynomial kernel chain."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("target"),
                DeclarationHandle.Create(Prefix + "target"), H("Extracted target span"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(Source),
                Blocks(Paragraph(Text("The span of the second arrow applied to all chain vectors except the final one."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("sourcebasis"),
                DeclarationHandle.Create(Prefix + "sourceBasis"), H("Source chain basis"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(Source),
                Blocks(Paragraph(Text("The independent chain vectors form a basis of their own span, including the singleton basis for a zero index."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("targetbasis"),
                DeclarationHandle.Create(Prefix + "targetBasis"), H("Target chain basis"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(Source),
                Blocks(Paragraph(Text("The independent output chain vectors form a basis of their own span, including the empty basis for a zero index."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("firstblock"),
                DeclarationHandle.Create(Prefix + "firstBlock"), H("Restricted first arrow"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(Source),
                Blocks(Paragraph(Text("Restrict the first arrow to the source chain span and project to the target chain span. Commutation of the two span projections makes this equal to the original first arrow on that source."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("secondblock"),
                DeclarationHandle.Create(Prefix + "secondBlock"), H("Restricted second arrow"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(Source),
                Blocks(Paragraph(Text("Restrict the second arrow to the source chain span and project to the target chain span. The resulting map equals the original second arrow on the source chain span."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("block"),
                DeclarationHandle.Create(Prefix + "block"), H("Extracted finite pencil"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(Source),
                Blocks(Paragraph(Text("The two restricted arrows, with their actual finite dimensional source and target spans, form a finite pencil."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("sourcecomplementprojection"),
                DeclarationHandle.Create(Prefix + "sourceComplementProjection"), H("Complementary source projection"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(Source),
                Blocks(Paragraph(Text("Subtract the source span projection from the identity and restrict its output to the kernel of the source span projection."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("targetcomplementprojection"),
                DeclarationHandle.Create(Prefix + "targetComplementProjection"), H("Complementary target projection"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(Source),
                Blocks(Paragraph(Text("Subtract the target span projection from the identity and restrict its output to the kernel of the target span projection."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("tensor-split"),
                DeclarationHandle.Create(Prefix + "tensor_split"), H("Tensor rank over the chain splitting"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(Source),
                Blocks(Paragraph(Text("For every second finite pencil, the tensor sum rank of the original pencil is the sum of the ranks for its extracted chain and its actual complementary pencil. The projected component factors through a surjection onto the source span and an injection from the target span; the complementary component has the corresponding factorization through the two projection kernels."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("horizontal-split"),
                DeclarationHandle.Create(Prefix + "horizontal_split"), H("Horizontal rank over the chain splitting"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(Source),
                Blocks(Paragraph(Text("The horizontal pair map has the sum of the horizontal ranks of the extracted chain and its simultaneous complement. Apply image rank additivity to the common target projection and the product of the two source projections."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("vertical-split"),
                DeclarationHandle.Create(Prefix + "vertical_split"), H("Vertical rank over the chain splitting"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(Source),
                Blocks(Paragraph(Text("The joint pair map has the sum of the vertical ranks of the extracted chain and its simultaneous complement. The target projection acts independently on the two output components."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("horizontal-rank"),
                DeclarationHandle.Create(Prefix + "horizontal_rank"), H("Horizontal rank of an extracted chain"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(Source),
                Blocks(Paragraph(Text("A chain of index r has horizontal pair rank r. The second restricted arrow is onto the entire target chain span."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("vertical-rank"),
                DeclarationHandle.Create(Prefix + "vertical_rank"), H("Vertical rank of an extracted chain"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(Source),
                Blocks(Paragraph(Text("A positive index r chain has vertical pair rank r+1. Its two arrows have trivial common kernel: the first arrow recovers all source coordinates after the initial coordinate, and the second arrow recovers the initial coordinate. A zero index chain is a common zero column and has vertical rank zero."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("tensor-rank"),
                DeclarationHandle.Create(Prefix + "tensor_rank"), H("Tensor rank of two right chains"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(Source),
                Blocks(Paragraph(Text("For actual extracted chains of indices r and s, the two term tensor sum has rank r times s, including zero indices. Their chain bases identify the two restricted arrows with the shift and truncated identity matrices. Transpose injectivity of the same orientation matrix follows by induction on the first row index, starting from the unshifted boundary."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("partialtranspose-rank"),
                DeclarationHandle.Create(Prefix + "partialTranspose_rank"), H("Tensor rank after one chain is dualized"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(Source),
                Blocks(Paragraph(Text("Dualizing the first of two extracted right chains gives tensor rank r times s plus min(r,s). The exact mixed rectangular pencil rank is reused after passing to the actual chain span bases and their dual bases."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("mixed-tensor-rank"),
                DeclarationHandle.Create(Prefix + "mixed_tensor_rank"), H("Tensor rank of opposite chain orientations"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(Source),
                Blocks(Paragraph(Text("Dualizing the second of two extracted right chains also gives tensor rank r times s plus min(r,s). This is the opposite orientation singular block formula, valid at zero indices as well."))), DescribeRole.Theorem))));
}
